do $$ declare t text; begin foreach t in array array['secondary_staff_details','secondary_staff_qualifications','secondary_staff_documents'] loop execute format('drop policy if exists %I on public.%I',t||'_read',t); execute format('drop policy if exists %I on public.%I',t||'_insert',t); execute format('drop policy if exists %I on public.%I',t||'_update',t); execute format('drop policy if exists %I on public.%I',t||'_delete',t); execute format('create policy %I on public.%I for select to authenticated using(exists(select 1 from public.school_memberships m where m.school_id=%I.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in(''owner'',''school_admin'',''headteacher'')))',t||'_restricted_read',t,t); execute format('create policy %I on public.%I for insert to authenticated with check(created_by=(select auth.uid()) and exists(select 1 from public.school_memberships m where m.school_id=%I.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in(''owner'',''school_admin'',''headteacher'')))',t||'_restricted_insert',t,t); execute format('create policy %I on public.%I for update to authenticated using(exists(select 1 from public.school_memberships m where m.school_id=%I.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in(''owner'',''school_admin'',''headteacher''))) with check(exists(select 1 from public.school_memberships m where m.school_id=%I.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in(''owner'',''school_admin'',''headteacher'')))',t||'_restricted_update',t,t,t); execute format('create policy %I on public.%I for delete to authenticated using(exists(select 1 from public.school_memberships m where m.school_id=%I.school_id and m.user_id=(select auth.uid()) and m.is_active and m.role in(''owner'',''school_admin'',''headteacher'')))',t||'_restricted_delete',t,t); end loop; end $$;
drop policy if exists conedu_staff_files_read on storage.objects;
create policy conedu_staff_files_read on storage.objects for select to authenticated using(bucket_id='conedu-staff-files' and exists(select 1 from public.school_memberships m where m.school_id=((storage.foldername(name))[1])::uuid and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','school_admin','headteacher')));
drop policy if exists conedu_staff_files_insert on storage.objects;
create policy conedu_staff_files_insert on storage.objects for insert to authenticated with check(bucket_id='conedu-staff-files' and exists(select 1 from public.school_memberships m where m.school_id=((storage.foldername(name))[1])::uuid and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','school_admin','headteacher')));
drop policy if exists conedu_staff_files_delete on storage.objects;
create policy conedu_staff_files_delete on storage.objects for delete to authenticated using(bucket_id='conedu-staff-files' and exists(select 1 from public.school_memberships m where m.school_id=((storage.foldername(name))[1])::uuid and m.user_id=(select auth.uid()) and m.is_active and m.role in('owner','school_admin','headteacher')));